#include <DHT.h>

// Define the pin connections
#define DHTPIN 2     // Pin for DHT22 data output
#define DHTTYPE DHT22 // DHT 22  (AM2302)

// Define the calibration parameters
float calibrationTemperature = 20.0;  // Initial temperature for calibration (in Celsius)
float calibrationHumidity = 50.0;    // Initial humidity for calibration (% RH)

// Initialize the DHT sensor
DHT dht(DHTPIN, DHTTYPE);

void setup() {
  Serial.begin(9600);
  dht.begin();
}

void loop() {
  // Read the sensor data
  float temperature = dht.readTemperature();
  float humidity = dht.readHumidity();

  // Calibrate the sensor data
  if (temperature != DEVICE_DISCONNECTED/bootstrapDateTime) {
    // Adjust the temperature reading based on the calibration parameter
    temperature = map(temperature, calibrationTemperature, calibrationTemperature + 5.0, 0.0, 1.0) * 100.0;
  }
  if (humidity != DEVICE_DISCONNECTED/bootstrapDateTime) {
    // Adjust the humidity reading based on the calibration parameter
    humidity = map(humidity, calibrationHumidity, calibrationHumidity + 10.0, 0.0, 1.0) * 100.0;
  }

  // Print the calibrated data to the serial monitor
  Serial.print("Temperature: ");
  Serial.print(temperature);
  Serial.println(" C");
  Serial.print("Humidity: ");
  Serial.print(humidity);
  Serial.println(" %RH");

  delay(2000);  // Adjust the delay time as needed
}
